import React, { useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Chip,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import {
  DEFAULT_SCOPE3_CATEGORIES_INCLUDED,
  GHG_SCOPE3_CATEGORY_OPTIONS,
} from '../../constants/ghgBoundaryBrsr';

export type OperationalBoundaryEaseValue = {
  reportingPeriodType: 'calendar_year' | 'financial_year';
  reportingPeriodEndMonth: number;
  baseYear: number;
  materialityThresholdPercent: number;
  scope1StationaryCombustion: boolean;
  scope1MobileCombustion: boolean;
  scope1ProcessEmissions: boolean;
  scope1FugitiveEmissions: boolean;
  scope2LocationBased: boolean;
  scope2MarketBased: boolean;
  scope3CategoriesIncluded: number[];
};

type OperationalBoundaryEaseProps<T extends OperationalBoundaryEaseValue> = {
  value: T;
  onChange: (next: T) => void;
  disabled?: boolean;
  part: 'period-and-scope1' | 'scope2' | 'scope3';
};

const SCOPE1_SOURCES = [
  {
    key: 'scope1StationaryCombustion' as const,
    title: 'Boilers & generators',
    hint: 'Furnace, DG set, LPG, coal, diesel on site.',
  },
  {
    key: 'scope1MobileCombustion' as const,
    title: 'Company vehicles',
    hint: 'Vans and trucks your company owns or leases.',
  },
  {
    key: 'scope1ProcessEmissions' as const,
    title: 'Process chemistry',
    hint: 'Gases released by the process itself, not just fuel.',
  },
  {
    key: 'scope1FugitiveEmissions' as const,
    title: 'Refrigerant leaks',
    hint: 'AC, chillers, and other gas leaks.',
  },
];

const SCOPE3_SHORT: Record<number, string> = {
  1: 'Goods you buy',
  2: 'Machines you buy',
  3: 'Fuel upstream',
  4: 'Inbound freight',
  5: 'Waste',
  6: 'Business travel',
  7: 'Staff commute',
  8: 'Leased assets in',
  9: 'Outbound freight',
  10: 'Customer processing',
  11: 'Product use',
  12: 'End of life',
  13: 'Leased assets out',
  14: 'Franchises',
  15: 'Investments',
};

const USUAL_SCOPE3 = [...DEFAULT_SCOPE3_CATEGORIES_INCLUDED];

function sameSet(left: number[], right: number[]): boolean {
  if (left.length !== right.length) return false;
  const sortedLeft = [...left].sort((a, b) => a - b);
  const sortedRight = [...right].sort((a, b) => a - b);
  return sortedLeft.every((value, index) => value === sortedRight[index]);
}

function ChoiceCard({
  title,
  hint,
  selected,
  badge,
  disabled,
  testId,
  onClick,
}: {
  title: string;
  hint: string;
  selected: boolean;
  badge?: string;
  disabled?: boolean;
  testId: string;
  onClick: () => void;
}) {
  return (
    <Box
      component="button"
      type="button"
      disabled={disabled}
      data-testid={testId}
      aria-pressed={selected}
      onClick={onClick}
      sx={{
        width: '100%',
        height: '100%',
        textAlign: 'left',
        cursor: disabled ? 'default' : 'pointer',
        borderRadius: 2,
        p: 1.5,
        border: '2px solid',
        borderColor: selected ? '#0f766e' : 'divider',
        bgcolor: selected ? alpha('#0f766e', 0.1) : 'background.paper',
        color: 'text.primary',
      }}
    >
      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 0.25 }}>
        <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>
          {title}
        </Typography>
        {badge ? <Chip size="small" label={badge} color="success" sx={{ height: 20, fontWeight: 700 }} /> : null}
        <Chip
          size="small"
          label={selected ? 'In' : 'Out'}
          variant={selected ? 'filled' : 'outlined'}
          color={selected ? 'primary' : 'default'}
          sx={{ height: 20, ml: 'auto !important' }}
        />
      </Stack>
      <Typography variant="caption" color="text.secondary">
        {hint}
      </Typography>
    </Box>
  );
}

function OperationalBoundaryEase<T extends OperationalBoundaryEaseValue>({
  value,
  onChange,
  disabled = false,
  part,
}: OperationalBoundaryEaseProps<T>) {
  const [showAllScope3, setShowAllScope3] = useState(false);
  const [showMonth, setShowMonth] = useState(false);
  const thisYear = new Date().getFullYear();
  const yearChoices = [thisYear, thisYear - 1, thisYear - 2];

  if (part === 'scope2') {
    return (
      <Grid container spacing={1.5} data-testid="ops-boundary-scope2" sx={{ mb: 2 }}>
        <Grid item xs={12} md={6}>
          <ChoiceCard
            title="Grid electricity"
            hint="The usual case. Power from your DISCOM or state grid."
            badge="Usual"
            selected={value.scope2LocationBased}
            disabled={disabled}
            testId="ops-scope2-grid"
            onClick={() => onChange({ ...value, scope2LocationBased: !value.scope2LocationBased })}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <ChoiceCard
            title="Green power contract"
            hint="Only if you have a PPA, REC, or green tariff."
            selected={value.scope2MarketBased}
            disabled={disabled}
            testId="ops-scope2-green"
            onClick={() => onChange({ ...value, scope2MarketBased: !value.scope2MarketBased })}
          />
        </Grid>
      </Grid>
    );
  }

  if (part === 'scope3') {
    const visible = GHG_SCOPE3_CATEGORY_OPTIONS.filter((option) => (
      showAllScope3 || USUAL_SCOPE3.includes(option.value as (typeof USUAL_SCOPE3)[number])
    ));
    const usingUsual = sameSet(value.scope3CategoriesIncluded, USUAL_SCOPE3);
    return (
      <Stack spacing={1.5} data-testid="ops-boundary-scope3" sx={{ mb: 2 }}>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          <Chip
            label={usingUsual ? 'Usual set is on' : 'Use the usual set'}
            color={usingUsual ? 'success' : 'default'}
            variant={usingUsual ? 'filled' : 'outlined'}
            onClick={() => onChange({ ...value, scope3CategoriesIncluded: [...USUAL_SCOPE3] })}
            disabled={disabled || usingUsual}
            data-testid="ops-scope3-usual"
          />
          <Chip
            label={showAllScope3 ? 'Hide rare categories' : 'Show all 15'}
            variant="outlined"
            onClick={() => setShowAllScope3((open) => !open)}
            data-testid="ops-scope3-show-all"
          />
        </Stack>
        <Typography variant="body2" color="text.secondary">
          Goods, freight, waste, and travel are already included. Turn a chip off if you truly skip it.
        </Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          {visible.map((option) => {
            const selected = value.scope3CategoriesIncluded.includes(option.value);
            return (
              <Chip
                key={option.value}
                label={SCOPE3_SHORT[option.value] || option.label}
                color={selected ? 'primary' : 'default'}
                variant={selected ? 'filled' : 'outlined'}
                disabled={disabled}
                data-testid={`ops-scope3-cat-${option.value}`}
                onClick={() => {
                  const next = selected
                    ? value.scope3CategoriesIncluded.filter((item) => item !== option.value)
                    : [...value.scope3CategoriesIncluded, option.value].sort((a, b) => a - b);
                  onChange({ ...value, scope3CategoriesIncluded: next });
                }}
              />
            );
          })}
        </Stack>
        <Accordion
          disableGutters
          elevation={0}
          sx={{ border: '1px solid', borderColor: 'divider', '&:before': { display: 'none' } }}
        >
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography variant="body2" sx={{ fontWeight: 700 }}>
              Screening cut-off (only if an auditor asks)
            </Typography>
          </AccordionSummary>
          <AccordionDetails>
            <TextField
              fullWidth
              size="small"
              type="number"
              label="Ignore categories under this % of your inventory"
              value={value.materialityThresholdPercent}
              disabled={disabled}
              onChange={(event) => onChange({
                ...value,
                materialityThresholdPercent: Math.min(25, Math.max(0, Number(event.target.value) || 0)),
              })}
              inputProps={{ min: 0, max: 25 }}
              helperText="5% is the usual screening cut-off."
            />
          </AccordionDetails>
        </Accordion>
      </Stack>
    );
  }

  return (
    <Stack spacing={2} data-testid="ops-boundary-period-scope1" sx={{ mb: 2 }}>
      <Box>
        <Typography variant="subtitle2" sx={{ fontWeight: 800, mb: 1 }}>
          Which year are we counting?
        </Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 1 }}>
          <Chip
            label="April–March"
            color={value.reportingPeriodType === 'financial_year' ? 'primary' : 'default'}
            variant={value.reportingPeriodType === 'financial_year' ? 'filled' : 'outlined'}
            disabled={disabled}
            data-testid="ops-period-fy"
            onClick={() => onChange({
              ...value,
              reportingPeriodType: 'financial_year',
              reportingPeriodEndMonth: 3,
            })}
          />
          <Chip
            label="January–December"
            color={value.reportingPeriodType === 'calendar_year' ? 'primary' : 'default'}
            variant={value.reportingPeriodType === 'calendar_year' ? 'filled' : 'outlined'}
            disabled={disabled}
            data-testid="ops-period-cy"
            onClick={() => onChange({
              ...value,
              reportingPeriodType: 'calendar_year',
              reportingPeriodEndMonth: 12,
            })}
          />
          {value.reportingPeriodType === 'financial_year' ? (
            <Chip size="small" label="Usual for India" color="success" variant="outlined" />
          ) : null}
        </Stack>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          {yearChoices.map((year) => (
            <Chip
              key={year}
              label={String(year)}
              color={value.baseYear === year ? 'primary' : 'default'}
              variant={value.baseYear === year ? 'filled' : 'outlined'}
              disabled={disabled}
              onClick={() => onChange({ ...value, baseYear: year })}
              data-testid={`ops-base-year-${year}`}
            />
          ))}
          <Chip
            label={showMonth ? 'Hide year-end month' : 'Different year-end'}
            variant="outlined"
            onClick={() => setShowMonth((open) => !open)}
          />
        </Stack>
        {showMonth ? (
          <TextField
            sx={{ mt: 1.5, maxWidth: 220 }}
            size="small"
            type="number"
            label="Year ends in month"
            value={value.reportingPeriodEndMonth}
            disabled={disabled}
            onChange={(event) => onChange({
              ...value,
              reportingPeriodEndMonth: Math.min(12, Math.max(1, Number(event.target.value) || 3)),
            })}
            helperText="March is 3. December is 12."
            inputProps={{ min: 1, max: 12 }}
          />
        ) : (
          <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.75 }}>
            {value.reportingPeriodType === 'financial_year'
              ? 'Financial year ending March. Change this only if your books close in another month.'
              : 'Calendar year ending December.'}
          </Typography>
        )}
      </Box>

      <Box>
        <Typography variant="subtitle2" sx={{ fontWeight: 800, mb: 0.5 }}>
          Fuel and leaks on your sites
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          These start on. Turn off anything you do not have.
        </Typography>
        <Grid container spacing={1.5}>
          {SCOPE1_SOURCES.map((source) => (
            <Grid item xs={12} sm={6} key={source.key}>
              <ChoiceCard
                title={source.title}
                hint={source.hint}
                selected={Boolean(value[source.key])}
                disabled={disabled}
                testId={`ops-scope1-${source.key}`}
                onClick={() => onChange({ ...value, [source.key]: !value[source.key] })}
              />
            </Grid>
          ))}
        </Grid>
      </Box>
    </Stack>
  );
}

export default OperationalBoundaryEase;
